@dataclass(frozen=True)
class ServiceConfig:
    """An API root (including any reverse-proxy prefix), never model supplied."""
    base_url: str
    api_key: str = field(default="", repr=False)
    session_id: str = field(default="", repr=False)

    def __post_init__(self) -> None:
        p = urllib.parse.urlsplit(self.base_url)
        if (p.scheme not in {"http", "https"} or not p.hostname or p.username or p.password
                or p.query or p.fragment or any(c.isspace() for c in self.base_url)):
            raise ValueError("Service base_url must be an HTTP(S) API root without credentials or query")
        try:
            p.port
        except ValueError as exc:
            raise ValueError("Invalid service port") from exc
        if not isinstance(self.api_key, str) or any(ord(c) < 32 or ord(c) == 127 for c in self.api_key):
            raise ValueError("Invalid API key encoding")
        if not isinstance(self.session_id, str) or (self.session_id and not re.fullmatch(r"[A-Za-z0-9._-]+", self.session_id)):
            raise ValueError("Invalid session cookie encoding")


def load_service_configs(path: str | Path) -> dict[str, ServiceConfig]:
    """Read {"services": {name: {base_url, api_key?, session_id?}}}. Never log secrets."""
    p = Path(path).expanduser()
    if p.stat().st_size > 1_048_576:
        raise ValueError("Service registry is too large")
    def unique(pairs):
        value = {}
        for key, item in pairs:
            if key in value:
                raise ValueError("Duplicate service registry key")
            value[key] = item
        return value
    try:
        raw = json.loads(p.read_text(encoding="utf-8"), object_pairs_hook=unique)
    except (ValueError, UnicodeError) as exc:
        raise ValueError("Invalid service registry JSON") from exc
    if not isinstance(raw, dict) or set(raw) != {"services"} or not isinstance(raw["services"], dict):
        raise ValueError("Service registry must contain only a services object")
    out: dict[str, ServiceConfig] = {}
    for name, value in raw["services"].items():
        if name not in SUPPORTED_OPERATIONS or not isinstance(value, dict) or set(value) - {"base_url", "api_key", "session_id"}:
            raise ValueError("Invalid service registry entry")
        if not isinstance(value.get("base_url"), str):
            raise ValueError("Service registry entry requires base_url")
        out[name] = ServiceConfig(**value)
    return out


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Refuse all redirects, including same-origin API-to-login redirects.
        # Neither service credentials nor cookies can follow an upstream URL.
        return None


class _UpstreamError(ValueError):
    def __init__(self, code: str, status: int = 502) -> None:
        self.code, self.status = code, status


def _norm(value: str) -> str:
    return " ".join(unicodedata.normalize("NFKC", value).casefold().split())


def _count(value: Any) -> int:
    if type(value) is not int or value < 0:
        raise _UpstreamError("invalid_pagination_count")
    return value


def _rows(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not all(isinstance(x, dict) for x in value):
        raise _UpstreamError("invalid_upstream_records")
    return value


_SAFE_FIELDS = frozenset({
    "id", "title", "name", "artistName", "artistId", "seriesId", "movieId", "albumId",
    "year", "monitored", "hasFile", "statistics", "seasonNumber", "episodeNumber",
    "status", "trackedDownloadStatus", "trackedDownloadState", "statusMessages", "errorMessage",
    "eventType", "date", "sourceTitle", "size", "sizeleft", "timeleft", "estimatedCompletionTime",
    "protocol", "downloadClient", "quality", "releaseDate", "inCinemas", "airDateUtc",
    "hash", "state", "progress", "dlspeed", "upspeed", "eta", "ratio", "amount_left",
    "downloaded", "uploaded", "availability", "num_seeds", "num_leechs", "priority", "category",
    "sonarrSeriesId", "sonarrEpisodeId", "radarrId", "seriesTitle", "episodeTitle", "episode_number",
    "season", "episode", "subtitles", "missing_subtitles", "audio_language",
    "friendly_name", "user", "full_title", "grandparent_title", "media_type", "started", "stopped",
    "duration", "play_duration", "player", "platform", "transcode_decision", "stream_count",
    "mediaType", "originalTitle", "originalName", "firstAirDate", "mediaInfo",
    "language", "code2", "code3", "forced", "hi", "hearing_impaired", "source", "resolution",
    "modifier", "episodeFileCount", "episodeCount", "trackFileCount", "trackCount", "albumCount",
    "series", "movie", "artist", "album",
})


def _public_row(row: dict[str, Any]) -> dict[str, Any]:
    """Do not emit credentials, local media paths, IP addresses or raw upstream objects."""
    def safe(value: Any, depth: int = 0) -> Any:
        if depth > 5:
            return None
        if isinstance(value, dict):
            return {key: safe(val, depth + 1) for key, val in value.items() if key in _SAFE_FIELDS}
        if isinstance(value, list):
            return [safe(item, depth + 1) for item in value[:100]]
        if isinstance(value, str):
            return value[:2048]
        if value is None or type(value) in {bool, int} or (type(value) is float and math.isfinite(value)):
            return value
        return None
    return safe(row)


class ServiceQueryAdapter:
    """Read-only adapter over explicit native API versions, with finite response/page budgets.

    No credentials or URL comes from a tool argument. Every dispatch revalidates
    the pair and current authenticated scopes. This class contains no HTTP write
    method, generic endpoint forwarding, automatic login, or application command.
    """

    def __init__(self, configs: Mapping[str, ServiceConfig], *, max_pages: int = 5,
                 page_size: int = 50, max_records: int = 250,
                 timeout_seconds: float = 8.0, max_response_bytes: int = 8_388_608) -> None:
        if (type(max_pages) is not int or not 1 <= max_pages <= 20
                or type(page_size) is not int or not 1 <= page_size <= 100
                or type(max_records) is not int or not 1 <= max_records <= 2000
                or not math.isfinite(timeout_seconds) or not 0 < timeout_seconds <= 60
                or type(max_response_bytes) is not int or not 1 <= max_response_bytes <= 33_554_432):
            raise ValueError("Invalid native adapter resource bounds")
        if any(name not in SUPPORTED_OPERATIONS or not isinstance(conf, ServiceConfig) for name, conf in configs.items()):
            raise ValueError("Invalid native service configuration")
        self.configs = dict(configs)
        self.max_pages, self.page_size, self.max_records = max_pages, page_size, max_records
        self.timeout_seconds, self.max_response_bytes = timeout_seconds, max_response_bytes
        self._opener = urllib.request.build_opener(_NoRedirect())

    def _get(self, service: str, path: str, audit: list[dict[str, Any]], *, text: bool = False) -> Any:
        cfg = self.configs[service]
        headers = {"Accept": "application/json", "User-Agent": "arrmes-native-read/1"}
        if cfg.api_key:
            if service == "qbittorrent":
                # Native stateless keys arrived in qBittorrent 5.2 / WebAPI
                # 2.14.1 and use Bearer, unlike the *arr API-key header.
                headers["Authorization"] = "Bearer " + cfg.api_key
            else:
                headers["X-Api-Key"] = cfg.api_key
        if service == "qbittorrent":
            headers["Referer"] = cfg.base_url.rstrip("/") + "/"
            if cfg.session_id:
                headers["Cookie"] = "SID=" + cfg.session_id
        req = urllib.request.Request(cfg.base_url.rstrip("/") + path, method="GET", headers=headers)
        try:
            with self._opener.open(req, timeout=self.timeout_seconds) as resp:
                audit.append({"method": "GET", "path": path, "status": int(resp.status)})
                deadline = time.monotonic() + self.timeout_seconds
                chunks: list[bytes] = []
                size = 0
                read_chunk = getattr(resp, "read1", resp.read)
                while True:
                    chunk = read_chunk(min(65536, self.max_response_bytes + 1 - size))
                    if time.monotonic() > deadline:
                        raise _UpstreamError("service_response_deadline_exceeded", 503)
                    size += len(chunk)
                    if size > self.max_response_bytes:
                        raise _UpstreamError("response_limit_exceeded")
                    if not chunk:
                        break
                    chunks.append(chunk)
                raw = b"".join(chunks)
                try:
                    decoded = raw.decode("utf-8")
                    def reject_nonfinite(_value):
                        raise ValueError("Non-finite upstream JSON number")
                    return decoded.strip() if text else json.loads(decoded, parse_constant=reject_nonfinite)
                except (ValueError, UnicodeError, RecursionError) as exc:
                    raise _UpstreamError("invalid_upstream_json") from exc
        except urllib.error.HTTPError as exc:
            audit.append({"method": "GET", "path": path, "status": int(exc.code)})
            error = ("service_authentication_failed" if exc.code in {401, 403} else
                     "service_api_version_or_route_unsupported" if exc.code == 404 else
                     "upstream_redirect_refused" if 300 <= exc.code < 400 else "upstream_http_error")
            status = int(exc.code)
            exc.close()
            raise _UpstreamError(error, status) from None
        except (urllib.error.URLError, TimeoutError, OSError):
            audit.append({"method": "GET", "path": path, "status": 503})
            raise _UpstreamError("service_unavailable", 503) from None

    def _paged(self, getter, *, records_key: str = "records", total_key: str = "totalRecords") -> tuple[list[dict[str, Any]], int, bool]:
        rows: list[dict[str, Any]] = []
        total = 0
        fingerprints: set[str] = set()
        seen_records: set[str] = set()
        first_total: int | None = None
        changed = False
        for page in range(self.max_pages):
            payload = getter(page)
            if not isinstance(payload, dict):
                raise _UpstreamError("invalid_upstream_page")
            incoming, reported = _rows(payload.get(records_key)), _count(payload.get(total_key))
            if reported < len(incoming):
                raise _UpstreamError("inconsistent_pagination_count")
            if first_total is None:
                first_total = reported
            changed = changed or reported != first_total
            total = max(total, reported)
            fingerprint = json.dumps(incoming, sort_keys=True)
            if not incoming or fingerprint in fingerprints:
                break
            fingerprints.add(fingerprint)
            unique_rows = []
            for row in incoming:
                key = json.dumps(row, sort_keys=True)
                if key in seen_records:
                    changed = True
                    continue
                seen_records.add(key)
                unique_rows.append(row)
            rows.extend(unique_rows[:self.max_records - len(rows)])
            if len(rows) >= total or len(rows) >= self.max_records:
                break
        return rows, total, changed or len(rows) < total

    def _result(self, service: str, args: dict[str, Any], rows: list[dict[str, Any]],
                total: int, truncated: bool, audit: list[dict[str, Any]], **extra: Any) -> AdapterObservation:
        query = args.get("query")
        filtered = bool(query and args["operation"] in {"library", "queue"})
        scanned_count = len(rows)
        if filtered:
            needle = _norm(query)
            rows = [r for r in rows if needle in _norm(str(r.get("title", r.get("artistName", r.get("name", "")))))]
        data = {"source": "native_api", "operation": args["operation"], "items": [_public_row(r) for r in rows],
                "returned_count": len(rows), "total_records": total, "truncated": truncated,
                "complete_listing": not truncated, **extra}
        if filtered:
            data.update(scanned_count=scanned_count, upstream_total_records=total,
                        total_records=None if truncated else len(rows))
        if query:
            data["query"] = query
        return AdapterObservation("partial" if truncated else "verified_ok", service, "service_query", 200,
                                  not truncated, data, audit)

    def execute(self, call: Call, principal: Principal, *, idempotency_key: str | None = None) -> AdapterObservation:
        audit: list[dict[str, Any]] = []
        if call.name != "service_query":
            raise InvalidCall("Native adapter accepts only service_query")
        args = validate_service_query(call.arguments)
        service = args["service"]
        if not principal.subject or SERVICE_PERMISSIONS[service] not in principal.scopes:
            return AdapterObservation("denied", service, call.name, 403, False, {"error": "permission_required"}, audit)
        if service not in self.configs:
            return AdapterObservation("error", service, call.name, 503, False, {"error": "service_not_configured"}, audit)
        try:
            if service in {"sonarr", "radarr", "lidarr"}:
                return self._arr(service, args, audit)
            return getattr(self, "_" + service)(args, audit)
        except _UpstreamError as exc:
            return AdapterObservation("error", service, call.name, exc.status, False, {"error": exc.code}, audit)

    def _arr(self, service: str, args: dict[str, Any], audit: list[dict[str, Any]]) -> AdapterObservation:
        version = "v1" if service == "lidarr" else "v3"
        root = "/api/" + version
        op = args["operation"]
        entity = {"sonarr": "series", "radarr": "movie", "lidarr": "artist"}[service]
        if op == "health":
            status = self._get(service, root + "/system/status", audit)
            issues = _rows(self._get(service, root + "/health", audit))
            if not isinstance(status, dict) or not isinstance(status.get("version"), str):
                raise _UpstreamError("invalid_service_status")
            if "appName" in status and str(status["appName"]).casefold() != service:
                raise _UpstreamError("service_identity_mismatch")
            return self._result(service, args, [], 0, False, audit, api_version=version,
                                server_version=status["version"], healthy=not issues,
                                issues=[{k: r[k] for k in ("source", "type", "message") if k in r} for r in issues])
        if op in {"queue", "history", "missing"}:
            endpoint = "/wanted/missing" if op == "missing" else "/" + op
            rows, total, truncated = self._paged(lambda page: self._get(service, root + endpoint + "?" + urllib.parse.urlencode({
                "page": page + 1, "pageSize": self.page_size,
                **({"includeSeries": "true"} if service == "sonarr" else {"includeMovie": "true"} if service == "radarr" else {"includeArtist": "true"}),
            }), audit))
        else:
            suffix = "/lookup?" + urllib.parse.urlencode({"term": args["query"]}) if op == "search" else ""
            all_rows = _rows(self._get(service, root + "/" + entity + suffix, audit))
            rows, total = all_rows[:self.max_records], len(all_rows)
            truncated = total > len(rows)
        return self._result(service, args, rows, total, truncated, audit, api_version=version)

    def _bazarr(self, args: dict[str, Any], audit: list[dict[str, Any]]) -> AdapterObservation:
        if args["operation"] == "health":
            payload = self._get("bazarr", "/api/system/health", audit)
            if not isinstance(payload, dict):
                raise _UpstreamError("invalid_service_status")
            issues = _rows(payload.get("data"))
            return self._result("bazarr", args, [], 0, False, audit, api_version="unversioned /api",
                                healthy=not issues, issues=[{k: r[k] for k in ("object", "issue") if k in r} for r in issues])
        movie = args["media_type"] == "movie"
        kind = "movies" if movie else "episodes"
        if args["operation"] == "missing":
            rows, total, truncated = self._paged(lambda page: self._get("bazarr", "/api/" + kind + "/wanted?" + urllib.parse.urlencode({
                "start": page * self.page_size, "length": self.page_size}), audit), records_key="data", total_key="total")
        else:
            library = "movies" if movie else "series"
            entities, _, incomplete = self._paged(lambda page: self._get("bazarr", "/api/" + library + "?" + urllib.parse.urlencode({
                "start": page * self.page_size, "length": self.page_size}), audit), records_key="data", total_key="total")
            exact = [r for r in entities if _norm(str(r.get("title", ""))) == _norm(args["query"])]
            if incomplete:
                return self._result("bazarr", args, [], 0, True, audit, reason="entity_lookup_incomplete")
            if len(exact) != 1:
                return AdapterObservation("clarify_required", "bazarr", "service_query", 409, False,
                                          {"slot": "reference", "reason": "subtitle_entity_not_uniquely_resolved"}, audit)
            if movie:
                rows = exact
            else:
                series_id = exact[0].get("sonarrSeriesId")
                if type(series_id) is not int or series_id <= 0:
                    raise _UpstreamError("invalid_resolved_entity_id")
                payload = self._get("bazarr", "/api/episodes?" + urllib.parse.urlencode({"seriesid[]": series_id}), audit)
                if not isinstance(payload, dict):
                    raise _UpstreamError("invalid_upstream_page")
                rows = _rows(payload.get("data"))
            total, truncated = len(rows), len(rows) > self.max_records
            rows = rows[:self.max_records]
        return self._result("bazarr", args, rows, total, truncated, audit, api_version="unversioned /api", media_type=args["media_type"])

    def _qbittorrent(self, args: dict[str, Any], audit: list[dict[str, Any]]) -> AdapterObservation:
        op = args["operation"]
        if op == "health":
            version = self._get("qbittorrent", "/api/v2/app/version", audit, text=True)
            api = self._get("qbittorrent", "/api/v2/app/webapiVersion", audit, text=True)
            if not re.fullmatch(r"v?\d+(?:\.\d+){1,3}(?:[-+].*)?", version) or not re.fullmatch(r"2\.\d+(?:\.\d+)?", api):
                raise _UpstreamError("unsupported_qbittorrent_api_version")
            return self._result("qbittorrent", args, [], 0, False, audit, api_version=api, server_version=version)
        if op == "activity":
            payload = self._get("qbittorrent", "/api/v2/transfer/info", audit)
            if not isinstance(payload, dict) or not all(type(payload.get(k)) in {int, float} and math.isfinite(payload[k]) and payload[k] >= 0 for k in ("dl_info_speed", "up_info_speed")):
                raise _UpstreamError("invalid_transfer_stats")
            return self._result("qbittorrent", args, [], 0, False, audit, api_version="v2", transfer={
                k: payload[k] for k in ("dl_info_speed", "up_info_speed", "dl_info_data", "up_info_data", "connection_status") if k in payload})
        rows: list[dict[str, Any]] = []
        seen: set[str] = set()
        exhausted = False
        for page in range(self.max_pages):
            incoming = _rows(self._get("qbittorrent", "/api/v2/torrents/info?" + urllib.parse.urlencode({
                "filter": args.get("torrent_filter", "all"), "limit": self.page_size,
                "offset": page * self.page_size, "sort": "hash"}), audit))
            hashes = [r.get("hash") for r in incoming]
            if any(not isinstance(h, str) or not re.fullmatch(r"[a-fA-F0-9]{40}|[a-fA-F0-9]{64}", h) for h in hashes):
                raise _UpstreamError("invalid_torrent_identity")
            if any(h in seen for h in hashes):
                break
            seen.update(hashes)
            remaining = self.max_records - len(rows)
            rows.extend(incoming[:remaining])
            if len(incoming) < self.page_size and len(incoming) <= remaining:
                exhausted = True
                break
            if len(rows) >= self.max_records:
                break
        # API has no total count; never invent one at the finite page budget.
        obs = self._result("qbittorrent", args, rows, len(rows), not exhausted, audit, api_version="v2")
        obs.data["total_records"] = obs.data["returned_count"] if exhausted else None
        return obs

    def _tautulli_data(self, path: str, audit: list[dict[str, Any]]) -> dict[str, Any]:
        payload = self._get("tautulli", path, audit)
        response = payload.get("response") if isinstance(payload, dict) else None
        if not isinstance(response, dict) or response.get("result") != "success" or not isinstance(response.get("data"), dict):
            raise _UpstreamError("tautulli_application_error")
        return response["data"]

    def _tautulli(self, args: dict[str, Any], audit: list[dict[str, Any]]) -> AdapterObservation:
        op = args["operation"]
        root = "/api/v2?"
        if op == "health":
            payload = self._tautulli_data(root + "cmd=get_tautulli_info", audit)
            version = payload.get("tautulli_version")
            if not isinstance(version, str):
                raise _UpstreamError("invalid_service_status")
            return self._result("tautulli", args, [], 0, False, audit, api_version="v2", server_version=version)
        if op == "activity":
            payload = self._tautulli_data(root + "cmd=get_activity", audit)
            rows = _rows(payload.get("sessions"))
            return self._result("tautulli", args, rows[:self.max_records], len(rows), len(rows) > self.max_records, audit, api_version="v2")
        rows, total, truncated = self._paged(lambda page: self._tautulli_data(root + urllib.parse.urlencode({
            "cmd": "get_history", "start": page * self.page_size, "length": self.page_size,
            "order_column": "date", "order_dir": "desc"}), audit), records_key="data", total_key="recordsFiltered")
        return self._result("tautulli", args, rows, total, truncated, audit, api_version="v2")

    def _seerr(self, args: dict[str, Any], audit: list[dict[str, Any]]) -> AdapterObservation:
        if args["operation"] == "health":
            payload = self._get("seerr", "/api/v1/status", audit)
            if not isinstance(payload, dict) or not isinstance(payload.get("version"), str):
                raise _UpstreamError("invalid_service_status")
            return self._result("seerr", args, [], 0, False, audit, api_version="v1", server_version=payload["version"])
        rows, total, truncated = self._paged(lambda page: self._get("seerr", "/api/v1/search?" + urllib.parse.urlencode({
            "query": args["query"], "page": page + 1}), audit), records_key="results", total_key="totalResults")
        return self._result("seerr", args, rows, total, truncated, audit, api_version="v1")

"""Conservative explicit-service NL routes; these are not v6 neural predictions."""
from __future__ import annotations

import re

from arrmes.protocol import Call
from .contract import SUPPORTED_OPERATIONS, validate_service_query

_SERVICES = re.compile(r"\b(sonarr|radarr|lidarr|bazarr|qbittorrent|qbt|tautulli|seerr|seer)\b", re.I)
_QUOTED = re.compile(r'"([^"\n]+)"|\'([^\'\n]+)\'')
_WRITE = re.compile(r"\b(download|delete|remove|restart|reboot|shutdown|pause|resume|stop|start|update|upgrade|scan|sync|grab|upload|add|change|set)\b", re.I)
_COMPOUND = re.compile(r"\b(and\s+then|then|and\s+also|after\s+that|followed\s+by)\b|[;\n]", re.I)
_UNSAFE = re.compile(r"\b(ignore|bypass|override|credentials?|passwords?|tokens?|api\s*keys?|instructions?|system\s*prompt|sudo|shell)\b", re.I)
_READ_WORDS = frozenset("""service entity please show list get tell me what which is are the a an my our in on for of
    whether currently check checks display inspect give report look up lookup catalog metadata search health healthy
    online reachable running queue history recent events library inventory missing wanted activity streams playing
    transfer stats statistics speed speeds bandwidth torrents torrent subtitles subtitle subs movie movies film films
    tv series episodes episode shows do does have has how many if matching""".split())


def route_service_query(query: str) -> Call | None:
    """Return a deterministic v3 read or abstention, or leave a v2 intent alone.

    Service names inside quoted entity text are ignored. Entity-bearing new
    lookup/subtitle routes require a single quoted surface span. Missing titles,
    conflicting scopes and compounds clarify/refuse instead of guessing.
    """
    if not isinstance(query, str) or not query.strip() or len(query) > 4000:
        return None
    quoted = [next(v for v in m.groups() if v is not None) for m in _QUOTED.finditer(query)]
    plain = _QUOTED.sub(" <ENTITY> ", query)
    mentions = _SERVICES.findall(plain)
    services = {"qbittorrent" if s.lower() == "qbt" else "seerr" if s.lower() == "seer" else s.lower() for s in mentions}
    if not services:
        return None
    if len(services) != 1 or _COMPOUND.search(plain):
        return Call("unsupported", {"reason": "complex"})
    service = next(iter(services))
    if _UNSAFE.search(plain):
        return Call("unsupported", {"reason": "unsafe"})
    if _WRITE.search(plain):
        # Preserve existing v2 confirmation-gated write intents; Bazarr and
        # Seerr mutations have no implementation and must not fall through.
        return Call("unsupported", {"reason": "out_of_scope"}) if service in {"bazarr", "seerr"} else None
    operations: set[str] = set()
    if re.search(r"\b(health|healthy|online|reachable|running)\b", plain, re.I):
        operations.add("health")
    if re.search(r"\bqueue\b", plain, re.I):
        operations.add("queue")
    if re.search(r"\b(history|recent\s+events)\b", plain, re.I):
        operations.add("history")
    if re.search(r"\b(library|inventory)\b", plain, re.I):
        operations.add("library")
    if re.search(r"\b(missing|wanted)\b", plain, re.I):
        operations.add("missing")
    if re.search(r"\b(activity|streams|playing|transfer\s+(?:stats|speeds?)|bandwidth)\b", plain, re.I):
        operations.add("activity")
    if re.search(r"\b(look\s*up|lookup|metadata\s+search|catalog\s+search|search\s+(?:the\s+)?(?:catalog|metadata))\b", plain, re.I):
        operations.discard("library")
        operations.add("search")
    if service == "bazarr" and re.search(r"\b(subtitles?|subs)\b", plain, re.I) and "missing" not in operations:
        operations.add("subtitles")
    if service == "qbittorrent" and re.search(r"\btorrents?\b", plain, re.I) and not operations:
        # Filtered v2 torrent_list already preserves transfer-state intent.
        if re.search(r"\b(paused|stopped|downloading|seeding|completed|stalled)\b", plain, re.I):
            return None
        operations.add("queue")
    if not operations:
        return None
    if len(operations) != 1:
        return Call("unsupported", {"reason": "complex"})
    operation = next(iter(operations))
    if operation not in SUPPORTED_OPERATIONS[service]:
        return Call("unsupported", {"reason": "out_of_scope"})
    # Existing entity-specific missing queries belong to the frozen v2 route.
    if operation == "missing" and service != "bazarr" and quoted:
        return None
    if operation == "queue" and service == "qbittorrent" and re.search(r"\b(paused|stopped|downloading|seeding|completed|stalled)\b", plain, re.I):
        return None
    args = {"service": service, "operation": operation}
    if operation in {"search", "subtitles"} or (quoted and (operation == "library" or (operation == "queue" and service == "qbittorrent"))):
        if len(quoted) != 1:
            return Call("clarify", {"slot": "title" if not quoted else "reference"})
        args["query"] = quoted[0]
    elif quoted:
        # A title-filtered health/history query is not silently broadened.
        return None if service == "tautulli" and operation == "history" else Call("clarify", {"slot": "scope"})
    if service == "bazarr" and operation in {"missing", "subtitles"}:
        movie = bool(re.search(r"\b(movies?|films?)\b", plain, re.I))
        tv = bool(re.search(r"\b(tv|series|episodes?|shows)\b", plain, re.I))
        if movie == tv:
            return Call("clarify", {"slot": "media_type"})
        args["media_type"] = "movie" if movie else "tv"
    # Unimplemented filters (language, date range, transfer state, exclusions,
    # ordering, etc.) must not silently turn into a broader inventory query.
    words = set(re.findall(r"[A-Za-z0-9_]+", _SERVICES.sub(" SERVICE ", plain).lower()))
    if words - _READ_WORDS:
        return Call("clarify", {"slot": "scope"})
    return Call("service_query", validate_service_query(args))

"""Native qBittorrent transfer controls with exact-target, single-use confirmation."""
from __future__ import annotations

import re
from typing import Any
import urllib.error
import urllib.parse
import urllib.request

from arrmes.adapters import AdapterObservation
from arrmes.planner import Principal
from arrmes.protocol import Call, InvalidCall, validate_call
from .native import ServiceQueryAdapter, _norm, _rows, _UpstreamError

CONFIRMATION_PREFIX = "native-qbt:"
TRANSFER_ACTIONS = frozenset({"torrent_pause", "torrent_resume"})
TORRENT_ACTIONS = TRANSFER_ACTIONS | {"torrent_list"}
_STOPPED = frozenset({"pausedup", "pauseddl", "stoppedup", "stoppeddl"})
_RUNNABLE = frozenset({"uploading", "downloading", "queuedup", "queueddl", "stalledup", "stalleddl",
                       "checkingup", "checkingdl", "forcedup", "forceddl", "metadl", "allocating",
                       "checkingresumedata", "moving"})
_HASH = re.compile(r"(?:[a-fA-F0-9]{40}|[a-fA-F0-9]{64})")


def _obs(status: str, name: str, code: int, data: dict[str, Any], audit, *, complete: bool = False) -> AdapterObservation:
    return AdapterObservation(status, "qbittorrent", name, code, complete, data, audit)


class NativeTransferAdapter:
    """Existing v2 pause/resume names, implemented against native WebAPI v2.

    Only exact unique catalogue names resolve. Mutation uses a hash pinned into
    the confirmation store's authenticated resolved_entity, never a fresh title
    search or an unsigned user argument. There is no direct-write mode.
    """

    def __init__(self, native: ServiceQueryAdapter, *, write_mode: str = "confirm", confirmation_store=None) -> None:
        if write_mode not in {"confirm", "shadow", "disabled"}:
            raise ValueError("Native transfer mode must be confirm, shadow, or disabled")
        from arrmes.live_adapter import WriteConfirmationStore
        self.native = native
        self.write_mode = write_mode
        self.confirmation_store = confirmation_store or WriteConfirmationStore()

    @staticmethod
    def _authorized(principal: Principal) -> bool:
        return bool(principal.subject and "torrents:manage" in principal.scopes)

    def _major_version(self, audit) -> int:
        version = self.native._get("qbittorrent", "/api/v2/app/version", audit, text=True)
        api = self.native._get("qbittorrent", "/api/v2/app/webapiVersion", audit, text=True)
        match = re.fullmatch(r"v?([45])\.(\d+)(?:\.\d+){0,2}(?:[-+].*)?", version)
        if not match or not re.fullmatch(r"2\.\d+(?:\.\d+)?", api):
            raise _UpstreamError("unsupported_qbittorrent_version", 501)
        if match[1] == "4" and int(match[2]) < 1:
            raise _UpstreamError("unsupported_qbittorrent_version", 501)
        return int(match[1])

    @staticmethod
    def _at_target(name: str, state: Any) -> bool:
        if not isinstance(state, str) or state.casefold() not in _STOPPED | _RUNNABLE:
            raise _UpstreamError("unrecognized_torrent_state")
        return state.casefold() in (_STOPPED if name == "torrent_pause" else _RUNNABLE)

    def _resolve(self, call: Call, audit) -> tuple[AdapterObservation | None, dict[str, Any]]:
        # Manage permission authorizes the prerequisite inventory read for this
        # exact transfer intent. It does not expose an unfiltered read action.
        listing = self.native._qbittorrent({"service": "qbittorrent", "operation": "queue"}, audit)
        if listing.status != "verified_ok" or not listing.data.get("complete_listing"):
            return _obs("clarify_required", call.name, 409,
                        {"slot": "reference", "reason": "torrent_inventory_incomplete"}, audit), {}
        exact = [r for r in listing.data["items"] if _norm(str(r.get("name", ""))) == _norm(call.arguments["title"])]
        if len(exact) != 1:
            return _obs("clarify_required", call.name, 409,
                        {"slot": "reference", "reason": "torrent_not_uniquely_resolved"}, audit), {}
        row = exact[0]
        info_hash = row.get("hash")
        if not isinstance(info_hash, str) or not _HASH.fullmatch(info_hash):
            raise _UpstreamError("invalid_torrent_identity")
        return None, {"hash": info_hash.lower(), "name": row["name"], "api_major": self._major_version(audit),
                      "prestate": row.get("state"), "service": "qbittorrent"}

    def execute(self, call: Call, principal: Principal, *, idempotency_key: str | None = None) -> AdapterObservation:
        call = validate_call(call.name, call.arguments, allow_v3=False)
        if call.name not in TORRENT_ACTIONS:
            raise InvalidCall("Native torrent adapter accepts only list/pause/resume")
        audit: list[dict[str, Any]] = []
        if call.name == "torrent_list":
            return self._list(call, principal, audit)
        if not self._authorized(principal):
            return _obs("denied", call.name, 403, {"error": "permission_required"}, audit)
        if self.write_mode == "disabled":
            return _obs("denied", call.name, 403, {"error": "writes_disabled"}, audit)
        if "qbittorrent" not in self.native.configs:
            return _obs("error", call.name, 503, {"error": "service_not_configured"}, audit)
        try:
            failure, entity = self._resolve(call, audit)
            if failure is not None:
                return failure
            if self._at_target(call.name, entity["prestate"]):
                return _obs("verified_ok", call.name, 200, {"hash": entity["hash"], "name": entity["name"],
                            "state": entity["prestate"], "changed": False}, audit, complete=True)
            summary = f"{'Pause' if call.name == 'torrent_pause' else 'Resume'} torrent '{entity['name']}' ({entity['hash']})"
            if self.write_mode == "shadow":
                return _obs("shadow_logged", call.name, 200, {"summary": summary, "resolved_entity": entity}, audit)
            token = self.confirmation_store.mint(principal, call, summary=summary, resolved_entity=entity)
            return _obs("confirmation_required", call.name, 200,
                        {"confirm_id": CONFIRMATION_PREFIX + token.confirm_id, "summary": summary,
                         "expires_at": token.expires_at, "resolved_entity": entity}, audit)
        except _UpstreamError as exc:
            return _obs("error", call.name, exc.status, {"error": exc.code}, audit)

    def _list(self, call: Call, principal: Principal, audit) -> AdapterObservation:
        if not principal.subject or "torrents:read" not in principal.scopes:
            return _obs("denied", call.name, 403, {"error": "permission_required"}, audit)
        if "qbittorrent" not in self.native.configs:
            return _obs("error", call.name, 503, {"error": "service_not_configured"}, audit)
        try:
            major = self._major_version(audit)
            state = call.arguments.get("state", "all")
            native_filter = "stopped" if state == "paused" and major == 5 else state
            args = {"service": "qbittorrent", "operation": "queue", "torrent_filter": native_filter}
            if "query" in call.arguments:
                args["query"] = call.arguments["query"]
            obs = self.native._qbittorrent(args, audit)
            # Preserve exact upstream state as well as the v2 semantic filter.
            obs.operation = "torrent_list"
            obs.data.update(operation="torrent_list", state=state, torrents=obs.data.pop("items"), count=obs.data["returned_count"])
            return obs
        except _UpstreamError as exc:
            return _obs("error", call.name, exc.status, {"error": exc.code}, audit)

    def _read_bound(self, entity: dict[str, Any], audit) -> dict[str, Any] | None:
        rows = _rows(self.native._get("qbittorrent", "/api/v2/torrents/info?" + urllib.parse.urlencode({"hashes": entity["hash"]}), audit))
        if len(rows) != 1:
            return None
        row = rows[0]
        if (not isinstance(row.get("hash"), str) or row["hash"].lower() != entity["hash"]
                or row.get("name") != entity["name"]):
            return None
        return row

    def _post_once(self, endpoint: str, info_hash: str, audit) -> tuple[int, dict[str, Any]]:
        """A single form POST. A timeout/5xx is unknown, never replayed."""
        cfg = self.native.configs["qbittorrent"]
        headers = {"Accept": "application/json", "Content-Type": "application/x-www-form-urlencoded",
                   "Referer": cfg.base_url.rstrip("/") + "/", "User-Agent": "arrmes-native-transfer/1"}
        if cfg.api_key:
            headers["Authorization"] = "Bearer " + cfg.api_key
        if cfg.session_id:
            headers["Cookie"] = "SID=" + cfg.session_id
        body = urllib.parse.urlencode({"hashes": info_hash}).encode("ascii")
        req = urllib.request.Request(cfg.base_url.rstrip("/") + endpoint, data=body, headers=headers, method="POST")
        try:
            with self.native._opener.open(req, timeout=self.native.timeout_seconds) as response:
                code = int(response.status)
                audit.append({"method": "POST", "path": endpoint, "status": code, "attempt": 1})
                if not 200 <= code < 300:
                    return code, {"error": "upstream_mutation_rejected", "replayed": False}
                return code, {}
        except urllib.error.HTTPError as exc:
            code = int(exc.code)
            exc.close()
            audit.append({"method": "POST", "path": endpoint, "status": code, "attempt": 1})
            return code, {"error": "upstream_mutation_rejected", "replayed": False,
                          "outcome": "unknown" if code >= 500 or 300 <= code < 400 else "rejected"}
        except (urllib.error.URLError, TimeoutError, OSError):
            audit.append({"method": "POST", "path": endpoint, "status": 503, "attempt": 1})
            return 503, {"error": "mutation_transport_error", "outcome": "unknown", "replayed": False}

    def confirm_write(self, confirm_id: str, principal: Principal, *, idempotency_key: str | None = None,
                      now: float | None = None) -> AdapterObservation:
        audit: list[dict[str, Any]] = []
        if not self._authorized(principal) or self.write_mode != "confirm":
            return _obs("denied", "confirm_write", 403, {"error": "permission_required_or_writes_disabled"}, audit)
        if not isinstance(confirm_id, str) or not confirm_id.startswith(CONFIRMATION_PREFIX):
            return _obs("denied", "confirm_write", 403, {"error": "confirmation_namespace_invalid"}, audit)
        token, error = self.confirmation_store.redeem(confirm_id[len(CONFIRMATION_PREFIX):], principal, now=now)
        if error or token is None:
            return _obs("denied", "confirm_write", 403, {"error": error or "confirmation_not_found"}, audit)
        if token.call_name not in TRANSFER_ACTIONS:
            return _obs("denied", "confirm_write", 403, {"error": "confirmation_action_mismatch"}, audit)
        entity, name = token.resolved_entity, token.call_name
        if (set(entity) != {"hash", "name", "api_major", "prestate", "service"}
                or entity.get("service") != "qbittorrent" or not isinstance(entity.get("hash"), str)
                or not _HASH.fullmatch(entity["hash"]) or entity.get("api_major") not in {4, 5}
                or not isinstance(entity.get("name"), str)):
            return _obs("denied", name, 403, {"error": "confirmation_binding_invalid"}, audit)
        if "qbittorrent" not in self.native.configs:
            return _obs("error", name, 503, {"error": "service_not_configured"}, audit)
        try:
            if self._major_version(audit) != entity["api_major"]:
                return _obs("denied", name, 409, {"error": "confirmation_service_version_changed"}, audit)
            row = self._read_bound(entity, audit)
            if row is None:
                return _obs("denied", name, 409, {"error": "confirmation_target_changed"}, audit)
            if self._at_target(name, row.get("state")):
                return _obs("verified_ok", name, 200, {"hash": entity["hash"], "name": entity["name"],
                            "state": row["state"], "changed": False}, audit, complete=True)
            method = ({"torrent_pause": "stop", "torrent_resume": "start"} if entity["api_major"] == 5
                      else {"torrent_pause": "pause", "torrent_resume": "resume"})[name]
            code, failure = self._post_once("/api/v2/torrents/" + method, entity["hash"], audit)
            if failure:
                return _obs("error", name, code, failure, audit)
            after = self._read_bound(entity, audit)
            if after is None:
                return _obs("dispatched", name, code, {"hash": entity["hash"], "changed": None,
                            "postcondition": "target_unavailable_after_dispatch"}, audit)
            complete = self._at_target(name, after.get("state"))
            return _obs("verified_ok" if complete else "dispatched", name, code,
                        {"hash": entity["hash"], "name": entity["name"], "state": after["state"],
                         "changed": True, "postcondition_verified": complete}, audit, complete=complete)
        except _UpstreamError as exc:
            return _obs("error", name, exc.status, {"error": exc.code}, audit)

"""Bounded independent native reads. No model-generated execution programs."""
from __future__ import annotations

import re

from .protocol import Call, validate_call
from .services import route_service_query

_PART = re.compile(r'''"[^"\n]*"|'[^'\n]*'|\b(?:and(?:\s+then)?|then)\b''', re.I)


def native_read_workflow(query: str, *, max_steps: int = 4) -> tuple[tuple[str, Call], ...] | Call | None:
    """Each clause must independently name a service and one supported read.

    Quoted titles keep their conjunctions. If any clause is unclear, unsupported
    or a write, the whole request abstains before dispatch. This is deliberately
    limited to independent reads: no inferred target, conditional, or write.
    """
    splits = [m for m in _PART.finditer(query) if not m.group().startswith(('"', "'"))]
    if not splits:
        return None
    if len(splits) + 1 > max_steps:
        return Call("unsupported", {"reason": "complex"})
    clauses: list[str] = []
    start = 0
    for match in splits:
        clauses.append(query[start:match.start()].strip())
        start = match.end()
    clauses.append(query[start:].strip())
    steps = []
    for clause in clauses:
        call = route_service_query(clause)
        if call is None or call.name != "service_query":
            return Call("unsupported", {"reason": "complex"})
        steps.append((clause, validate_call(call.name, call.arguments)))
    return tuple(steps)
